types.IsoDirectory:
/* ISO9660 recording date/time (7 bytes) */
typedef struct __attribute__((packed)) {
    u8 yearsSince1900;
    u8 month;
    u8 day;
    u8 hour;
    u8 minute;
    u8 second;
    s8 offset;
} IsoDirectoryDateTime;

/* ISO9660 directory record (both-endian fields: LSB first, MSB copy) */
typedef struct __attribute__((packed)) {
    u8 recLen; /* 0x0 */
    u8 earLen; /* 0x1 */
    u32 lbn; /* 0x2 */
    u32 lbnMsb; /* 0x6 */
    u32 size; /* 0xA */
    u32 sizeMsb; /* 0xE */
    IsoDirectoryDateTime dateTime; /* 0x12 */
    u8 flags; /* 0x19, 2 = directory */
    u8 fileUnitSize; /* 0x1A */
    u8 interleaveGap; /* 0x1B */
    u16 volSeqNum; /* 0x1C */
    u16 volSeqNumMsb; /* 0x1E */
    u8 nameLen; /* 0x20 */
    char name[0]; /* 0x21 */
} IsoDirectory;

/* ISO9660 path table record (L table) */
typedef struct __attribute__((packed)) {
    u8 nameLen; /* 0x0 */
    u8 earLen; /* 0x1 */
    u32 lbn; /* 0x2 */
    u16 parentNum; /* 0x6 */
    char name[0]; /* 0x8 */
} IsoPath;

types.IsofsBlkDevData:
/* sceBLKGetDeviceData() result kept in IsofsUnit.blkDev (only maxLbn known) */
typedef struct {
#if FW_VERSION == 100
    u8 unk0[0x854];
#else
    u8 unk0[0x858];
#endif
    u32 maxLbn;
} IsofsBlkDevData;

types.IsofsCacheEntry:
/* cache entry (0x30), 16 of them */
typedef struct {
    union {
        char umdId[32]; /* 0x0 */
        u32 umdIdW[8];
    };
    s8 used; /* 0x20 */
    s8 unk21;
    s16 refCount; /* 0x22 */
    u32 lbn; /* 0x24 */
    u32 size; /* 0x28 */
    void *memory; /* 0x2C */
} IsofsCacheEntry;
typedef char chk_IsofsCacheEntry[(sizeof(IsofsCacheEntry) == 0x30) ? 1 : -1];

types.IsofsDir:
/* parsed path table entry (0x38) */
typedef struct {
    u8 nameLen; /* 0x0 */
    u8 earLen; /* 0x1 */
    u32 lbn __attribute__((packed, aligned(2))); /* 0x2 */
    u16 parentNum; /* 0x6 */
    char name[32]; /* 0x8 */
    u32 dirNum; /* 0x28 */
    u32 dirLevel; /* 0x2C */
    u32 lbnSize; /* 0x30 */
    u32 unk34;
} IsofsPath;
typedef char chk_IsofsPath[(sizeof(IsofsPath) == 0x38) ? 1 : -1];

/* open directory (iob->i_private for dopen) (0x18) */
typedef struct {
    IsoDirectory *isoDir; /* 0x0 */
    IsofsPath *paths; /* 0x4 */
    void *fplData; /* 0x8 */
    u32 lbnSize; /* 0xC */
    u32 dirRecLen; /* 0x10 */
    u32 lbn; /* 0x14 */
} IsofsDir;
typedef char chk_IsofsDir[(sizeof(IsofsDir) == 0x18) ? 1 : -1];

types.IsofsFd:
typedef s64 SceOff;
typedef int SceMode;
/* iofilemgr file descriptor block (1.00, 0x80) */
typedef struct SceIoIob {
    s32 i_flgs; /* 0x0 */
    s32 i_unit; /* 0x4 */
    void *i_de; /* 0x8 */
    s32 d_type; /* 0xC */
    void *i_private; /* 0x10 */
    void *i_cwd; /* 0x14 */
    SceOff i_fpos; /* 0x18 */
} SceIoIob;
typedef struct {
    u16 year;
    u16 month;
    u16 day;
    u16 hour;
    u16 minute;
    u16 second;
    u32 microsecond;
} ScePspDateTime;
/* iofilemgr stat (0x58) */
typedef struct {
    SceMode st_mode; /* 0x0 */
    u32 st_attr; /* 0x4 */
    SceOff st_size; /* 0x8 */
    ScePspDateTime st_ctime; /* 0x10 */
    ScePspDateTime st_atime; /* 0x20 */
    ScePspDateTime st_mtime; /* 0x30 */
    u32 st_private[6]; /* 0x40 */
} SceIoStat;
typedef struct IsofsFdw IsofsFdw;
typedef struct IsofsUnit IsofsUnit;
typedef struct IsofsFile IsofsFile;
/* list of file slots (0x24) */
typedef struct IsofsFd {
    u16 unk0;
    u16 filesCount; /* 0x2 */
    u32 idx; /* 0x4 */
    u32 unk8;
    u32 unkC;
    SceUID heapId; /* 0x10 */
    u32 unk14;
    IsofsFile *files; /* 0x18 */
    IsofsFdw *fdw; /* 0x1C */
    IsofsUnit *unit; /* 0x20 */
} IsofsFd;

